func parseSSHCmd(cmd string) (string, string) {
	ss := strings.SplitN(cmd, " ", 2)
	if len(ss) != 2 || len(ss[1]) < 2 || ss[1][0] != '\'' || ss[1][len(ss[1])-1] != '\'' {
		return "", ""
	}
	// SSH commands must contain exactly one quoted repository path. Rejecting
	// embedded quotes prevents extra shell arguments from reaching git.
	args := ss[1][1 : len(ss[1])-1]
	if strings.ContainsRune(args, '\'') {
		return "", ""
	}
	return ss[0], args
}

