if (path.win32.isAbsolute(p)) {
  let stripped = p
  let parsed = path.win32.parse(stripped)
  while (parsed.root) {
    stripped = stripped.substr(parsed.root.length)
    parsed = path.win32.parse(stripped)
  }
  entry.path = stripped
  const r = path.win32.parse(p).root
  this.warn('TAR_ENTRY_INFO', `stripping ${r} from absolute path`, {
    entry,
    path: p,
  })
}

