import { BlockList } from 'netmask'

const privateRanges = [
  '0.0.0.0/8', '10.0.0.0/8', '100.64.0.0/10', '127.0.0.0/8',
  '169.254.0.0/16', '172.16.0.0/12', '192.0.0.0/24', '192.0.2.0/24',
  '192.168.0.0/16', '198.18.0.0/15', '198.51.100.0/24', '203.0.113.0/24',
  '224.0.0.0/4', '240.0.0.0/4'
].map((range) => new BlockList(range))

const isPrivateIPv4 = (ip) => {
  const parts = ip.split('.')
  if (parts.length > 4 || !parts.every((part) => /^\d+$/.test(part))) return false

  let value = 0
  for (let i = 0; i < parts.length; i++) {
    const part = Number(parts[i])
    const bits = i === parts.length - 1 ? 8 * (5 - parts.length) : 8
    if (!Number.isSafeInteger(part) || part >= Math.pow(2, bits)) return false
    value = value * Math.pow(2, bits) + part
  }
  const canonical = [value >>> 24, (value >>> 16) & 255, (value >>> 8) & 255, value & 255].join('.')
  return privateRanges.some((range) => range.contains(canonical))
}

export default (ip) => (
  (typeof ip === 'string' && isPrivateIPv4(ip)) ||
  /^(::f{4}:)?10\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})$/i.test(ip) ||
  /^(::f{4}:)?192\.168\.([0-9]{1,3})\.([0-9]{1,3})$/i.test(ip) ||
  /^(::f{4}:)?172\.(1[6-9]|2\d|30|31)\.([0-9]{1,3})\.([0-9]{1,3})$/i.test(ip) ||
  /^(::f{4}:)?127\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})$/i.test(ip) ||
  /^(::f{4}:)?169\.254\.([0-9]{1,3})\.([0-9]{1,3})$/i.test(ip) ||
  /^f[cd][0-9a-f]{2}:/i.test(ip) ||
  /^fe80:/i.test(ip) ||
  /^::1$/.test(ip) ||
  /^::$/.test(ip)
)

