 13	 */
 14	export async function lookupWebFinger(
 15	  resource: URL | string,
 16	): Promise<ResourceDescriptor | null> {
 17	  if (typeof resource === "string") resource = new URL(resource);
 18	  let protocol = "https:";
 19	  let server: string;
 20	  if (resource.protocol === "acct:") {
 21	    const atPos = resource.pathname.lastIndexOf("@");
 22	    if (atPos < 0) return null;
 23	    server = resource.pathname.substring(atPos + 1);
 24	    if (server === "") return null;
 25	  } else {
 26	    protocol = resource.protocol;
 27	    server = resource.host;
 28	  }
 29	  let url = new URL(`${protocol}//${server}/.well-known/webfinger`);
 30	  url.searchParams.set("resource", resource.href);
 31	  let redirected = 0;
 32	  while (true) {
 33	    logger.debug(
 34	      "Fetching WebFinger resource descriptor from {url}...",
 35	      { url: url.href },
 36	    );
 37	    let response: Response;
 38	    try {
 39	      response = await fetch(url, {
 40	        headers: { Accept: "application/jrd+json" },
 41	        redirect: "manual",
 42	      });
 43	    } catch (error) {
