 11	 * @returns The resource descriptor, or `null` if not found.
 12	 * @since 0.2.0
 13	 */
 14	export async function lookupWebFinger(
 15	  resource: URL | string,
 16	): Promise<ResourceDescriptor | null> {
 17	  if (typeof resource === "string") resource = new URL(resource);
 18	  let protocol = "https:";
 19	  let server: string;
 20	  if (resource.protocol === "acct:") {
 21	    const atPos = resource.pathname.lastIndexOf("@");
 22	    if (atPos < 0) return null;
 23	    server = resource.pathname.substring(atPos + 1);
 24	    if (server === "") return null;
 25	  } else {
 26	    protocol = resource.protocol;
 27	    server = resource.host;
 28	  }
 29	  let url = new URL(`${protocol}//${server}/.well-known/webfinger`);
 30	  url.searchParams.set("resource", resource.href);
 31	  let redirected = 0;
 32	  while (true) {
 33	    logger.debug(
 34	      "Fetching WebFinger resource descriptor from {url}...",
 35	      { url: url.href },
 36	    );
 37	    let response: Response;
 38	    try {
 39	      response = await fetch(url, {
 40	        headers: { Accept: "application/jrd+json" },
 41	        redirect: "manual",
 42	      });
 43	    } catch (error) {
 44	      logger.debug(
 45	        "Failed to fetch WebFinger resource descriptor: {error}",
 46	        { url: url.href, error },
 47	      );
 48	      return null;
 49	    }
 50	    if (
 51	      response.status >= 300 && response.status < 400 &&
 52	      response.headers.has("Location")
 53	    ) {
 54	      redirected++;
 55	      if (redirected >= MAX_REDIRECTION) {
 56	        logger.error(
 57	          "Too many redirections ({redirections}) while fetching WebFinger " +
 58	            "resource descriptor.",
 59	          { redirections: redirected },
 60	        );
 61	        return null;
 62	      }
 63	      const redirectedUrl = new URL(
 64	        response.headers.get("Location")!,
 65	        response.url == null || response.url === "" ? url : response.url,
 66	      );
 67	      if (redirectedUrl.protocol !== url.protocol) {
 68	        logger.error(
 69	          "Redirected to a different protocol ({protocol} to " +
 70	            "{redirectedProtocol}) while fetching WebFinger resource " +
 71	            "descriptor.",
 72	          {
 73	            protocol: url.protocol,
 74	            redirectedProtocol: redirectedUrl.protocol,
 75	          },
 76	        );
 77	        return null;
 78	      }
 79	      url = redirectedUrl;
 80	      continue;
 81	    }
 82	    if (!response.ok) {
 83	      logger.debug(
 84	        "Failed to fetch WebFinger resource descriptor: {status} {statusText}.",
 85	        {
 86	          url: url.href,
 87	          status: response.status,
 88	          statusText: response.statusText,
 89	        },
 90	      );
 91	      return null;
 92	    }
 93	    try {
 94	      return await response.json() as ResourceDescriptor;
 95	    } catch (e) {
 96	      if (e instanceof SyntaxError) {
 97	        logger.debug(
 98	          "Failed to parse WebFinger resource descriptor as JSON: {error}",
 99	          { error: e },
100	        );
101	        return null;
102	      }
103	      throw e;
104	    }
105	  }
106	}

