module.exports = function(image, output, cb) {
  module.exports.cmd(image, output);
  execFile('convert', module.exports.args(image, output), {timeout: 30000}, function(e, stdout, stderr) {
    if (e) { return cb(e); }
    if (stderr) { return cb(new Error(stderr)); }

    return cb(null, output.versions);
  });
};

/**
 * Get convert arguments without invoking a shell.
 */
module.exports.args = function(image, output) {
  var args = [image.path, '-auto-orient', '-strip', '-write', 'mpr:' + image.path, '+delete'];

  for (var i = 0; i < output.versions.length; i++) {
    var version = output.versions[i];
    var last = (i === output.versions.length - 1);
    var crop = module.exports.crop(image, version.aspect);
    var resize = module.exports.resize(crop, version);

    args.push('mpr:' + image.path);
    if (version.quality) { args.push('-quality', String(version.quality)); }
    if (version.background) { args.push('-background', version.background); }
    if (version.flatten) { args.push('-flatten'); }
    if (crop.geometry) { args.push('-crop', crop.geometry); }
    if (resize) { args.push('-resize', resize); }
    if (last) {
      args.push(version.path);
    } else {
      args.push('-write', version.path, '+delete');
    }
  }

  return args;
};

